customCSS:
.t, .history { color: #7e8e91; }
.join { color: #a6e22e; }
.part, .quit { color: #7e8e91; }
.kick, .error { color: #f92672; }
.notice { color: #e6db74; }
.action { color: #ae81ff; }
.mode, .nick, .topic, .server { color: #66d9ef; }
.highlight { color: #f8f8f2; background-color: #403d3d; border-left: 3px solid #ae81ff; padding-left: 8px; }
.reply { color: #7e8e91; border-left: 2px solid #66d9ef; padding-left: 6px; }
.oper { color: #1b1d1e; background-color: #e6db74; }
.reactions { color: #66d9ef; background-color: #232526; }
.card { background-color: #232526; border-color: #7e8e91; }
.card-title { color: #66d9ef; }
.card-desc { color: #7e8e91; }
.daychange { color: #7e8e91; border-color: #232526; }
